{
  "county_id": "HVA05",
  "actions": [
    {
      "action_id": "equal-fast-lane",
      "action": "Proposed: Same-week physician assessment and direct-access diagnostics for red-flag symptoms in public health centres, regardless of employment or insurance.",
      "rationale": "The optimiser picked equal-fast-lane for HVA05, assuming EUR 1,493,400 a year and a central estimate of 39.9 deaths postponed per year (range 5-78.6), and the county's patients waiting over 6 months for specialised care are 54.83 per 10 000 against 36 nationally.",
      "owner_role": "Accountable owner: Wellbeing services county primary care.",
      "indicator": "Indicator to monitor: Waiting time for elective outpatient medical visit (physician) in primary health care exceeds 7 days from assessment of the need for treatment, % appointments kept.",
      "roadmap_measure": "2.5.2"
    },
    {
      "action_id": "screening-reminders",
      "action": "Proposed: Send a second kit with plain-language, multilingual instructions to non-responders; measure the gain as a stepped pilot.",
      "rationale": "The portfolio includes screening-reminders for HVA05, where colorectal screening participation is 75.0% against the 80% target, with an expected gain of 1.5-4.5 percentage points closing about 60% of the gap.",
      "owner_role": "Accountable owner: Wellbeing services county screening unit.",
      "indicator": "Indicator to monitor: Proportion of invited to colorectal cancer screening who attended, %.",
      "roadmap_measure": "1.3.1"
    },
    {
      "action_id": "self-sampling",
      "action": "Proposed: Mail a self-sampling kit with the second reminder to everyone who has not attended.",
      "rationale": "The portfolio includes self-sampling for HVA05, where cervical screening participation is 76.3% against the 80% target, with an expected gain of 1.5-3.67 percentage points closing about 82% of the gap.",
      "owner_role": "Accountable owner: Wellbeing services county screening unit.",
      "indicator": "Indicator to monitor: Proportion of women invited to cervical cancer screening (smear test) who attended, %.",
      "roadmap_measure": "2.4.4"
    }
  ],
  "evidence_does_not_support": "equal-fast-lane: The route gap is observational and from one cancer type. How much of it a fast lane closes is a scenario parameter, not a measured effect."
}

